//! MarkdownFormatting against the shared oracle. Port of md.win `MarkdownFormattingTests`.
//!
//! `fixtures/formatting-vectors.json` is the cross-port contract for the formatting commands
//! (`docs/formatting.md`): 127 `format` and 10 `wrapTyped` vectors generated by md.win's
//! `tools/formatting-reference/` and copied verbatim into md, md.macOS, md.Android, md.win and
//! here. Every offset is a UTF-16 code unit; `expected` is the edit to the original text and the
//! selection in the result, or JSON null for no edit. No vector is skipped; a disputed one is
//! changed in the reference first. Every vector runs through both entry points (`&str` and
//! `Utf16Text`).

mod common;

use std::sync::OnceLock;

use md_core::editing::markdown_formatting::{self, FormatEdit, FormatOp};
use md_core::text::utf16::Utf16Text;
use serde_json::Value;

fn vectors(section: &str) -> &'static [Value] {
    static ROOT: OnceLock<Value> = OnceLock::new();
    let root = ROOT
        .get_or_init(|| serde_json::from_str(&common::fixture_text("formatting-vectors.json")).expect("vectors parse"));
    root[section].as_array().unwrap_or_else(|| panic!("no {section} array"))
}

fn vector(section: &str, id: &str) -> &'static Value {
    let mut matching = vectors(section).iter().filter(|v| v["id"] == id);
    let v = matching.next().unwrap_or_else(|| panic!("no {section} vector {id}"));
    assert!(matching.next().is_none(), "two {section} vectors {id}");
    v
}

fn ids(section: &str) -> Vec<&'static str> {
    vectors(section).iter().map(|v| v["id"].as_str().expect("id")).collect()
}

fn op(name: &str) -> FormatOp {
    match name {
        "bold" => FormatOp::Bold,
        "italic" => FormatOp::Italic,
        "code" => FormatOp::Code,
        "strikethrough" => FormatOp::Strikethrough,
        "link" => FormatOp::Link,
        "heading1" => FormatOp::Heading1,
        "heading2" => FormatOp::Heading2,
        "heading3" => FormatOp::Heading3,
        "heading4" => FormatOp::Heading4,
        "heading5" => FormatOp::Heading5,
        "heading6" => FormatOp::Heading6,
        "headingCycle" => FormatOp::HeadingCycle,
        "bulletList" => FormatOp::BulletList,
        "taskList" => FormatOp::TaskList,
        "quote" => FormatOp::Quote,
        "indent" => FormatOp::Indent,
        "outdent" => FormatOp::Outdent,
        _ => panic!("Unknown op in the vectors: {name}"),
    }
}

fn str_of<'a>(v: &'a Value, key: &str) -> &'a str {
    v[key].as_str().unwrap_or_else(|| panic!("{key} is not a string in {v}"))
}

fn offset(v: &Value, key: &str) -> isize {
    isize::try_from(v[key].as_i64().unwrap_or_else(|| panic!("{key} is not an integer in {v}"))).expect("fits")
}

fn unsigned(v: &Value, key: &str) -> usize {
    usize::try_from(v[key].as_u64().unwrap_or_else(|| panic!("{key} is not an offset in {v}"))).expect("fits")
}

fn assert_edit(expected: &Value, actual: Option<&FormatEdit>, id: &str) {
    if expected.is_null() {
        assert!(actual.is_none(), "{id}: expected no edit, got {actual:?}");
        return;
    }
    let actual = actual.unwrap_or_else(|| panic!("{id}: expected an edit, got none"));
    let want = FormatEdit {
        start: unsigned(expected, "start"),
        end: unsigned(expected, "end"),
        text: str_of(expected, "text").to_owned(),
        selection_start: unsigned(expected, "selectionStart"),
        selection_end: unsigned(expected, "selectionEnd"),
    };
    assert_eq!(&want, actual, "{id}");
}

#[test]
fn the_oracle_is_whole() {
    assert_eq!(127, vectors("format").len());
    assert_eq!(10, vectors("wrapTyped").len());
}

/// md.win's `[Theory] Format(id)` over every `format` vector.
#[test]
fn format() {
    for id in ids("format") {
        let v = vector("format", id);
        let text = str_of(v, "text");
        let (s, e, o) = (offset(v, "selectionStart"), offset(v, "selectionEnd"), op(str_of(v, "op")));
        let edit = markdown_formatting::format(text, s, e, o);
        assert_edit(&v["expected"], edit.as_ref(), id);
        let edit16 = markdown_formatting::format_utf16(&Utf16Text::new(text), s, e, o);
        assert_edit(&v["expected"], edit16.as_ref(), id);
    }
}

/// md.win's `[Theory] WrapTyped(id)` over every `wrapTyped` vector.
#[test]
fn wrap_typed() {
    for id in ids("wrapTyped") {
        let v = vector("wrapTyped", id);
        let (text, typed) = (str_of(v, "text"), str_of(v, "typed"));
        let (s, e) = (offset(v, "selectionStart"), offset(v, "selectionEnd"));
        let edit = markdown_formatting::wrap_typed(text, s, e, typed);
        assert_edit(&v["expected"], edit.as_ref(), id);
        let edit16 = markdown_formatting::wrap_typed_utf16(&Utf16Text::new(text), s, e, &Utf16Text::new(typed));
        assert_edit(&v["expected"], edit16.as_ref(), id);
    }
}

#[test]
fn a_reversed_selection_is_the_same_selection() {
    assert_eq!(
        markdown_formatting::format("say hello", 4, 9, FormatOp::Bold),
        markdown_formatting::format("say hello", 9, 4, FormatOp::Bold)
    );
    assert_eq!(markdown_formatting::wrap_typed("ab", 0, 2, "*"), markdown_formatting::wrap_typed("ab", 2, 0, "*"));
}

#[test]
fn apply_to_splices_the_original() {
    assert_eq!(
        "say **hello** now",
        markdown_formatting::format("say hello now", 4, 9, FormatOp::Bold).expect("an edit").apply_to("say hello now")
    );
}

// The port's own, beyond md.win's: the two places it decides what md.win leaves to an exception.

/// md.win throws for a selection outside the text; md.macOS (the source of truth) clamps it into
/// the text, and so does this port — never a panic in the editor.
#[test]
fn a_selection_outside_the_text_is_clamped_as_on_the_mac() {
    assert_eq!(
        markdown_formatting::format("abc", 5, 7, FormatOp::Bold),
        markdown_formatting::format("abc", 3, 3, FormatOp::Bold)
    );
    assert_eq!(
        markdown_formatting::format("abc", -2, 99, FormatOp::Italic),
        markdown_formatting::format("abc", 0, 3, FormatOp::Italic)
    );
    assert_eq!(None, markdown_formatting::wrap_typed("abc", 4, 9, "*"));
    assert_eq!(markdown_formatting::wrap_typed("abc", -1, 2, "_"), markdown_formatting::wrap_typed("abc", 0, 2, "_"));
}

/// The edit's offsets are UTF-16 units and `apply_to` splices by them, so a text with a non-BMP
/// scalar before the selection round-trips.
#[test]
fn offsets_are_utf16_units_through_apply_to() {
    let text = "\u{1F44B} hi";
    let edit = markdown_formatting::format(text, 3, 5, FormatOp::Code).expect("an edit");
    assert_eq!((edit.start, edit.end, edit.selection_start, edit.selection_end), (3, 5, 4, 6));
    assert_eq!("\u{1F44B} `hi`", edit.apply_to(text));
    let units = Utf16Text::new(text);
    assert_eq!(Utf16Text::new("\u{1F44B} `hi`"), edit.apply_to_utf16(&units));
}
